#!/usr/bin/env bash
# СУДИТ: scripts/backlog-recheck.sh
# СУД: только в рабочем дереве
# probe_D411 — «Проверка» закрытого D411 дословно: прибор сверки долга называет наибольшую спайку правок законной.
# Вынесена из текста пункта в пробу 15 ноября 2026 (скептик opus по D1295, M2): спайку прибор считает по снимку карты
#   `mcp-server/visualization/project-graph-data.json`, а он под .gitignore — в клоне коммита
#   (`scripts/archive-checks-after-commit.sh`) его нет, и ответ «НЕ ИЗМЕРЕНА» шёл напоминанием «не держатся» на каждом
#   коммите, задевшем прибор сверки (27 из 400). Маркер «только в рабочем дереве» выводит пробу из такого суда; судит её
#   недельный прогон архива в настоящем дереве.
# Код: 0 — спайка законна; иначе 1 (как у прежней строки «Проверки»).
cd "${CLAUDSOUL_REPO:-$(git rev-parse --show-toplevel 2>/dev/null)}" 2>/dev/null || exit 2
BACKLOG_RECHECK_VERBOSE=1 bash scripts/backlog-recheck.sh 2>&1 | grep -q "✓ D411 .*спайка данных законна"
